            [
                'category' => 'Yii2',
                'question' => 'Как ввести очереди в legacy Yii2-проект через yii2-queue?',
                'answer' => "В Yii2 нет встроенных очередей — нужен пакет **`yiisoft/yii2-queue`**. Внедряется постепенно, как и в Laravel, но настройка отличается.\n\n**Шаги внедрения**:\n\n1. **`composer require yiisoft/yii2-queue`**.\n2. **Зарегистрировать компонент** в `config/common.php` (для web + console). Стартуй с **`db`-драйвера** — никакого Redis на старте, очередь в той же БД.\n3. **`php yii migrate --migrationPath=@vendor/yiisoft/yii2-queue/src/drivers/db/migrations`** — таблица `queue`.\n4. **Класс джоба** — реализует `\\yii\\queue\\JobInterface` с методом `execute(\$queue)`.\n5. **Запуск воркера**: `php yii queue/listen` (long-running) или `php yii queue/run` (выполнить и выйти, удобно для cron).\n6. **Идемпотентность** обязательна — джоб может выполниться повторно при падении. Делай `findOne()` / `firstOrCreate`-аналог по уникальному ключу.\n7. **Перевод на Redis** — `\\yii\\queue\\redis\\Queue` или RabbitMQ — когда поток растёт. Меняется только конфиг.\n\n**Что НЕ выносить в очередь**:\n\n- HTTP-ответы, нужные пользователю прямо сейчас.\n- Чтение для текущего запроса — это кэш, не очередь.\n- Работа с `\$_FILES` запроса — воркер их не увидит.\n\n**Подводные камни Yii2**:\n\n- **`Yii::\$app->user`** в console-контексте **не существует** (нет сессии). Идентификатор пользователя передавай **в свойствах джоба**, не полагайся на `Yii::\$app->user`.\n- **DI-биндинги** в console-конфиге и web-конфиге **разные**. Если джоб требует сервис — он должен быть в обоих конфигах или в `common.php`.\n- **TTR (time-to-run)** — таймаут джоба. По умолчанию `300s`. Если воркер `kill -9` посередине, через `ttr` секунд джоб вернётся в очередь — **двойное выполнение**. Лечится идемпотентностью и `ttr < worker_timeout`.\n- **Lazy-load AR** — если кидаешь AR в свойство джоба, он сериализуется через `__sleep()`. При выполнении джоб **подтягивает свежее** состояние через primary key. Аналог Laravel `SerializesModels`.",
                'code_example' => "<?php\n// config/common.php\n'components' => [\n    'queue' => [\n        'class' => \\yii\\queue\\db\\Queue::class,\n        'db' => 'db',\n        'tableName' => '{{%queue}}',\n        'channel' => 'default',\n        'mutex' => \\yii\\mutex\\MysqlMutex::class,\n        'ttr' => 300,\n        'attempts' => 3,\n        'as log' => \\yii\\queue\\LogBehavior::class,\n    ],\n],\n\n// Джоб с идемпотентностью\nclass SendWelcomeEmailJob extends \\yii\\base\\BaseObject implements \\yii\\queue\\JobInterface\n{\n    public int \$userId;\n\n    public function execute(\$queue): void\n    {\n        \$user = User::findOne(\$this->userId);\n        if (!\$user) {\n            return; // юзер удалён — нечего делать\n        }\n\n        \$cacheKey = \"welcome_sent:{\$user->id}\";\n        if (Yii::\$app->cache->exists(\$cacheKey)) {\n            return; // уже отправлено в предыдущей попытке\n        }\n\n        Yii::\$app->mailer\n            ->compose('welcome', ['user' => \$user])\n            ->setTo(\$user->email)\n            ->send();\n\n        Yii::\$app->cache->set(\$cacheKey, true, 86400 * 30);\n    }\n}\n\n// Контроллер — кладём в очередь\npublic function actionRegister()\n{\n    \$user = new User(['email' => Yii::\$app->request->post('email')]);\n    \$user->save();\n\n    Yii::\$app->queue->push(new SendWelcomeEmailJob(['userId' => \$user->id]));\n    // Отложенный\n    Yii::\$app->queue->delay(60)->push(new SendReminderJob(['userId' => \$user->id]));\n}\n\n# Запуск воркера в supervisor\n# command=php /var/www/yii queue/listen --verbose=1 --color=0",
                'code_language' => 'php',
                'difficulty' => 3,
                'topic' => 'yii2.refactoring',
            ],
            [
                'category' => 'Yii2',
                'question' => 'Как начать писать characterization tests в Yii2-проекте на Codeception без тестов?',
                'answer' => "Та же стратегия, что в Laravel, но другой инструмент: **Codeception** с suites **`unit` / `functional` / `acceptance`** + **`yii2-codeception`**.\n\n**Идея — characterization tests** (Майкл Физерс): фиксируешь **текущее поведение** (баг это или нет — пока не важно), получаешь сеть, под которой можно рефакторить.\n\n**Конкретный план для legacy Yii2**:\n\n1. **Suite `functional`** — тесты через симулированный HTTP-запрос без браузера (аналог Laravel Feature). Не требует поднятого сервера — Codeception ходит во внутренний `yii\\web\\Application` напрямую.\n2. **Suite `unit`** — изолированные тесты классов. Наследуй `\\Codeception\\Test\\Unit`, доступ к фикстурам через `_fixtures()`.\n3. **Фикстуры вместо `RefreshDatabase`** — `\\yii\\test\\Fixture` с `dataFile` / `modelClass`. Перед каждым тестом таблица **очищается и перезаливается**.\n4. **Тестовое окружение** — `config/test.php` со сменой `db` на `sqlite :memory:` или отдельную `*_test`-БД.\n5. **HTTP-моки** — в Yii2 нет аналога `Http::fake()`. Создавай **интерфейс HttpClient**, регистрируй в DI: прод-реализация бьёт по сети, тестовая возвращает заготовленные ответы.\n6. **Mailer-моки** — `Yii::\$app->set('mailer', new \\app\\components\\TestMailer())` в `_before()` теста или в bootstrap.\n7. **Очереди в тестах** — `Yii::\$app->queue` подменить на `\\yii\\queue\\sync\\Queue` (выполняет джоб сразу) или собирать кинутые джобы в массив для assert-ов.\n\n**Подводные камни**:\n\n- **`Yii::\$app` пересоздаётся** между тестами через bootstrap. Поэтому состояние Service Locator (`->set('mailer', ...)`) **обнуляется** — мокать нужно в каждом тесте или в общем `_before()`.\n- **Глобальный bootstrap** не должен делать ничего тяжёлого (внешние HTTP, миграции) — иначе CI тормозит.\n- **`->seeRecord(User::class, ['email' => ...])`** — аналог Laravel `assertDatabaseHas`. Удобно для characterization tests.\n\n**Стратегия покрытия legacy**:\n\n- Не «100% coverage перед рефактором» — **покрой тот контроллер, что собираешься менять**.\n- **Snapshot-аналог** — `assertJsonStringEqualsJsonFile` с заранее сохранённым `expected.json` для эндпоинтов с большой выдачей.\n- Сложные методы AR — переноси по одному в новый сервис **с unit-тестом**, старый код остаётся работать.",
                'code_example' => "<?php\n// tests/functional/RegistrationCest.php — characterization test\nclass RegistrationCest\n{\n    public function _fixtures(): array\n    {\n        return [\n            'users' => [\n                'class' => UserFixture::class,\n                'dataFile' => codecept_data_dir() . 'users.php',\n            ],\n        ];\n    }\n\n    public function _before(FunctionalTester \$I): void\n    {\n        // Моки — каждый тест\n        Yii::\$app->set('mailer', new \\app\\tests\\stubs\\TestMailer());\n        Yii::\$app->set('queue', new \\yii\\queue\\sync\\Queue());\n    }\n\n    public function registrationCreatesUser(FunctionalTester \$I): void\n    {\n        \$I->amOnRoute('site/register');\n        \$I->submitForm('#register-form', [\n            'RegisterForm[email]' => 'jane@example.com',\n            'RegisterForm[password]' => 'secret123',\n        ]);\n\n        // Текущее поведение — фиксируем\n        \$I->seeResponseCodeIs(302);\n        \$I->seeRecord(User::class, ['email' => 'jane@example.com']);\n\n        // Snapshot-style для богатого ответа JSON-эндпоинта\n        \$I->sendGet('/api/me');\n        \$I->seeResponseJsonMatchesJsonPath('\$.email');\n        \$I->seeResponseEquals(file_get_contents(codecept_data_dir() . 'me-response.json'));\n    }\n}\n\n// tests/_data/users.php — фикстура\nreturn [\n    'admin' => ['id' => 1, 'email' => 'admin@example.com', 'status' => 10],\n    'user' => ['id' => 2, 'email' => 'user@example.com', 'status' => 10],\n];\n\n// config/test.php\nreturn [\n    'components' => [\n        'db' => ['dsn' => 'sqlite::memory:'],\n        'mailer' => ['class' => \\app\\tests\\stubs\\TestMailer::class],\n        'queue' => ['class' => \\yii\\queue\\sync\\Queue::class],\n    ],\n];",
                'code_language' => 'php',
                'difficulty' => 3,
                'topic' => 'yii2.refactoring',
            ],
            [
                'category' => 'Yii2',
                'question' => 'Где использовать Behaviors в Yii2 (а где НЕ стоит)?',
                'answer' => "**Behavior** в Yii2 — способ навесить переиспользуемое поведение на компонент без наследования. Хорошо подходит для **cross-cutting** задач, но часто превращается в свалку бизнес-логики.\n\n**Где использовать (good fit)**:\n\n- **Аудит-таймстампы** — `TimestampBehavior` ставит `created_at`/`updated_at` автоматически на `BEFORE_INSERT`/`BEFORE_UPDATE`. Стандартное решение, не пиши руками.\n- **Кто создал/обновил** — `BlameableBehavior` пишет `created_by = Yii::\$app->user->id`. Cross-cutting, не относится к доменной логике.\n- **Slug из заголовка** — `SluggableBehavior` генерит `slug = slugify(title)`. Чисто техническая задача.\n- **Soft-delete** — кастомный behavior с `BEFORE_DELETE` → ставит `deleted_at` и блокирует реальное удаление. Универсально.\n- **Versioning / audit log** — копирование в audit-таблицу при изменении. Cross-cutting, переиспользуется на N моделей.\n- **Access Control** — `AccessControl` (filter behavior) на контроллере — навешивает проверку прав на actions.\n\n**Где НЕ стоит (anti-patterns)**:\n\n- **Бизнес-логика заказа в OrderBehavior** — поведение бизнес-объекта НЕ должно жить в behavior. Логику в Service/Action, AR — тонкая модель.\n- **Behavior, мутирующий несколько моделей** — нарушает Single Responsibility, его трудно тестировать.\n- **Behavior с внешними I/O** — отправка писем, HTTP-вызовы прямо в `afterSave` через behavior. Делает save() непредсказуемым и медленным (попадает в транзакцию).\n- **Behavior как «магическая прокладка»** — когда из кода вызова не видно, какие поля заполняются автоматически. Junior-у потом нечитаемо.\n\n**Правила**:\n\n- Behavior нужен, если **то же самое поведение** требуется на **3+ моделях**. На одной — пиши прямо в модель.\n- Behavior должен быть **stateless** и не дергать I/O.\n- Имя метода-обработчика события начинай с `on...` или `handle...` — видно, что это листенер behavior-а, а не публичный API.\n\n**Связь с PHP traits**:\n\n- **Trait** — копипаст кода в класс на этапе компиляции. Никаких событий, никакого DI.\n- **Behavior** — отдельный объект, **прицепляется в runtime**, реагирует на события owner-а через `events()`. Можно отцепить (`detachBehavior()`).",
                'code_example' => "<?php\n// ✅ Хороший behavior — cross-cutting, без I/O\nclass SoftDeleteBehavior extends \\yii\\base\\Behavior\n{\n    public function events(): array\n    {\n        return [\n            \\yii\\db\\ActiveRecord::EVENT_BEFORE_DELETE => 'softDelete',\n        ];\n    }\n\n    public function softDelete(\\yii\\base\\ModelEvent \$event): void\n    {\n        /** @var \\yii\\db\\ActiveRecord \$owner */\n        \$owner = \$this->owner;\n        \$owner->deleted_at = time();\n        \$owner->save(false, ['deleted_at']);\n        \$event->isValid = false; // отменяем настоящий DELETE\n    }\n}\n\n// Применение — много моделей, одинаковая логика\nclass User extends \\yii\\db\\ActiveRecord\n{\n    public function behaviors(): array\n    {\n        return [\n            \\yii\\behaviors\\TimestampBehavior::class,\n            [\n                'class' => \\yii\\behaviors\\BlameableBehavior::class,\n                'createdByAttribute' => 'created_by',\n                'updatedByAttribute' => null, // только при создании\n            ],\n            SoftDeleteBehavior::class,\n        ];\n    }\n}\n\n// ❌ Антипаттерн — бизнес-логика в behavior\nclass OrderProcessingBehavior extends \\yii\\base\\Behavior\n{\n    public function events(): array\n    {\n        return [\\yii\\db\\ActiveRecord::EVENT_AFTER_INSERT => 'processOrder'];\n    }\n\n    public function processOrder(): void\n    {\n        // ↓ это бизнес-логика, тут нечего делать в behavior\n        \$this->owner->charge();\n        Yii::\$app->mailer->compose('order')->send();\n        Yii::\$app->queue->push(new GenerateInvoiceJob());\n    }\n}\n// Вместо этого — OrderController вызывает PlaceOrder-Service",
                'code_language' => 'php',
                'difficulty' => 2,
                'topic' => 'yii2.refactoring',
            ],
            [
                'category' => 'Yii2',
                'question' => 'Как использовать AR scenarios как границу безопасной массовой загрузки данных?',
                'answer' => "**Сценарий (scenario)** в Yii2 — способ сказать модели «для какого случая её сейчас используют». Управляет двумя вещами: какие **правила валидации** применяются и какие **атрибуты считаются safe** для массовой загрузки через `load()`.\n\n**Зачем нужны scenarios**:\n\n- **Mass assignment безопасность**. Из формы регистрации `\$user->load(\$_POST)` должен пустить `email/password`, но НЕ пустить `is_admin/balance`. Сценарий определяет, какие поля **safe**.\n- **Разные правила для разных операций**. На регистрации `password` обязателен, на профиле — необязателен (не вводят повторно).\n- **Граница доверия**. Сценарий = контракт «эти поля разрешены из HTTP».\n\n**Как работает**:\n\n- В модели метод **`scenarios(): array`** возвращает `['scenario_name' => ['attr1', 'attr2', ...]]`.\n- **`safe`-attributes** для сценария — те, что попадают через `load()` и валидируются по `rules()` с этим сценарием.\n- Если не определять `scenarios()` явно — все правила работают для всех сценариев, safe-атрибуты собираются из `rules()` автоматически.\n- Сценарий ставится: `\$user->scenario = User::SCENARIO_REGISTRATION` ПЕРЕД `load()`.\n\n**Стандартный паттерн refactor-а**:\n\n1. Найди контроллер, где `\$model->load(Yii::\$app->request->post())` грузит **всё подряд** — потенциальный mass assignment.\n2. Объяви в модели **константы сценариев** и метод `scenarios()`.\n3. Ставь сценарий **до** `load()`. Лишние поля из POST просто не попадут.\n4. Тест на безопасность — кидаешь в POST `is_admin = 1`, проверяешь, что после `load()` модель не получила admin-флаг.\n\n**Подводные камни**:\n\n- **`SCENARIO_DEFAULT`** — стартовый сценарий. Если забыл проставить — модель работает с дефолтным набором safe-атрибутов.\n- **`scenarios()` переопределяет автоматику** — если объявил, нужно перечислить **все** нужные атрибуты явно, иначе исчезнут.\n- **`!` префикс** перед именем атрибута (`'!is_admin'`) — поле валидируется, но НЕ safe (нельзя через `load()`). Удобно для серверных атрибутов.\n- **Старый код с `attributes = \$_POST`** — обходит scenarios. Заменяй на `load()`.",
                'code_example' => "<?php\nclass User extends \\yii\\db\\ActiveRecord\n{\n    public const SCENARIO_REGISTRATION = 'registration';\n    public const SCENARIO_PROFILE_UPDATE = 'profile-update';\n    public const SCENARIO_ADMIN_EDIT = 'admin-edit';\n\n    public function rules(): array\n    {\n        return [\n            [['email', 'password'], 'required', 'on' => self::SCENARIO_REGISTRATION],\n            ['email', 'email'],\n            ['password', 'string', 'min' => 8, 'on' => [self::SCENARIO_REGISTRATION]],\n            ['display_name', 'string', 'max' => 100, 'on' => [self::SCENARIO_PROFILE_UPDATE]],\n            // is_admin — отдельно для админ-сценария\n            ['is_admin', 'boolean', 'on' => self::SCENARIO_ADMIN_EDIT],\n        ];\n    }\n\n    public function scenarios(): array\n    {\n        return [\n            self::SCENARIO_REGISTRATION => ['email', 'password'],\n            self::SCENARIO_PROFILE_UPDATE => ['display_name', 'avatar'],\n            self::SCENARIO_ADMIN_EDIT => ['email', 'is_admin', 'role'],\n        ];\n    }\n}\n\n// Контроллер — регистрация\npublic function actionRegister()\n{\n    \$user = new User();\n    \$user->scenario = User::SCENARIO_REGISTRATION;\n\n    if (\$user->load(Yii::\$app->request->post()) && \$user->save()) {\n        return \$this->redirect(['dashboard']);\n    }\n    // Если в POST прилетит is_admin=1, он будет ПРОИГНОРИРОВАН\n    return \$this->render('register', ['model' => \$user]);\n}\n\n// Тест — проверка mass assignment защиты\npublic function testRegistrationIgnoresAdminFlag(): void\n{\n    \$user = new User();\n    \$user->scenario = User::SCENARIO_REGISTRATION;\n    \$user->load([\n        'User' => [\n            'email' => 'jane@example.com',\n            'password' => 'secret123',\n            'is_admin' => 1, // должно быть проигнорировано\n            'balance' => 999999,\n        ],\n    ]);\n\n    \$this->assertSame('jane@example.com', \$user->email);\n    \$this->assertNull(\$user->is_admin);\n    \$this->assertNull(\$user->balance);\n}",
                'code_language' => 'php',
                'difficulty' => 2,
                'topic' => 'yii2.refactoring',
            ],
        ];
    }
